package main

import "regexp"

// CountValid returns how many lines match the fixed email-like pattern.
// BUG: regexp.MustCompile(pattern) re-parses and rebuilds the automaton on
// EVERY call inside the loop, instead of once - unusably slow for large
// inputs since the pattern never changes.
func CountValid(lines []string) int {
	pattern := `^user-\d+@example\.com$`
	count := 0
	for _, line := range lines {
		re := regexp.MustCompile(pattern)
		if re.MatchString(line) {
			count++
		}
	}
	return count
}

