package main

import (
	"fmt"
	"testing"
	"time"
)

func TestCountValidCorrectness(t *testing.T) {
	lines := []string{"user-1@example.com", "nope", "user-42@example.com", "user-x@example.com"}
	got := CountValid(lines)
	if got != 2 {
		t.Fatalf("got %d, want 2", got)
	}
}

func TestCountValidEmpty(t *testing.T) {
	if got := CountValid(nil); got != 0 {
		t.Fatalf("got %d, want 0", got)
	}
}

func TestCountValidPerformance(t *testing.T) {
	n := 150000
	lines := make([]string, n)
	expected := 0
	for i := 0; i < n; i++ {
		if i%3 == 0 {
			lines[i] = fmt.Sprintf("user-%d@example.com", i)
			expected++
		} else {
			lines[i] = fmt.Sprintf("nope-%d", i)
		}
	}

	start := time.Now()
	got := CountValid(lines)
	elapsed := time.Since(start)

	if got != expected {
		t.Fatalf("large-input count wrong: got %d, want %d", got, expected)
	}
	if elapsed > 500*time.Millisecond {
		t.Fatalf("CountValid took %v for n=%d, expected < 500ms (looks like the "+
			"regexp is still being recompiled every iteration)", elapsed, n)
	}
}

