package main

import "regexp"

// Correct output but still recompiles inside the loop via a helper - the
// compile cost is paid every iteration either way.
func compilePattern() *regexp.Regexp {
	return regexp.MustCompile(`^user-\d+@example\.com$`)
}

func CountValid(lines []string) int {
	count := 0
	for _, line := range lines {
		re := compilePattern()
		if re.MatchString(line) {
			count++
		}
	}
	return count
}
